/**
 * Photos, the portrait and project screenshots.
 *
 * You do not edit this file to add images. Drop files into the `public` folder
 * and run `npm run photos` (it also runs automatically on `npm run dev` and
 * `npm run build`):
 *
 *   public/photos/<category>/<name>.jpg   →  gallery, grouped by folder name
 *   public/portrait.jpg                   →  the portrait in the About section
 *   public/projects/<slug>.jpg            →  a project screenshot
 *
 * Until there are real photos, the gallery shows the placeholders below.
 */

import generated from "./media.generated.json";

export type MediaAsset = {
  src: string;
  width: number;
  height: number;
  /** Tiny blurred preview shown while the full image loads. */
  blurDataURL: string;
};

export type Photo = MediaAsset & {
  category: string;
  title: string;
  alt: string;
};

type MediaManifest = {
  photos: Photo[];
  portrait: MediaAsset | null;
  projects: Record<string, MediaAsset>;
};

const manifest = generated as unknown as MediaManifest;

export type GalleryItem =
  | ({ kind: "photo"; id: string } & Photo)
  | {
      kind: "placeholder";
      id: string;
      category: string;
      title: string;
      width: number;
      height: number;
      /** Index into the placeholder colour tones. */
      tone: number;
    };

const placeholderFrames: Array<[category: string, width: number, height: number]> = [
  ["Portraits", 4, 5],
  ["Street", 3, 2],
  ["Events", 1, 1],
  ["Landscape", 16, 10],
  ["Portraits", 2, 3],
  ["Events", 3, 2],
  ["Street", 4, 5],
  ["Landscape", 3, 2],
  ["Events", 2, 3],
  ["Portraits", 1, 1],
  ["Landscape", 4, 5],
  ["Street", 3, 2],
];

const placeholders: GalleryItem[] = placeholderFrames.map(
  ([category, width, height], index) => ({
    kind: "placeholder",
    id: `placeholder-${index + 1}`,
    category,
    title: `Frame ${String(index + 1).padStart(2, "0")}`,
    width,
    height,
    tone: index,
  }),
);

/** Real photos when there are any, otherwise the placeholders. */
export const galleryItems: GalleryItem[] =
  manifest.photos.length > 0
    ? manifest.photos.map((photo) => ({
        kind: "photo",
        id: photo.src,
        ...photo,
      }))
    : placeholders;

export const hasRealPhotos = manifest.photos.length > 0;

export const portrait: MediaAsset | null = manifest.portrait;

export function projectScreenshot(slug: string): MediaAsset | null {
  return manifest.projects[slug] ?? null;
}
